import{_ as a,a0 as o,w as i,s as n,I as s,x as t,a1 as r,A as l,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"CIO 真正需要 DevOps 团队做什么？ | LCTT x X-CMD","titleTemplate":false,"description":"CIO 真正需要 DevOps 团队做什么？ | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"CIO 真正需要 DevOps 团队做什么？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"CIO 真正需要 DevOps 团队做什么？ | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20171205 What DevOps teams really need from a CIO","title":"CIO 真正需要 DevOps 团队做什么？","tag":"201804","desc":""},"relativePath":"201804/20171205 What DevOps teams really need from a CIO.md","filePath":"[post].md"}'),O={name:"201804/20171205 What DevOps teams really need from a CIO.md"};function v(m,e,D,f,T,u){const p=o("Link");return i(),n("div",null,[e[18]||(e[18]=s("h1",{id:"cio-真正需要-devops-团队做什么",tabindex:"-1"},[t("CIO 真正需要 DevOps 团队做什么？ "),s("a",{class:"header-anchor",href:"#cio-真正需要-devops-团队做什么","aria-label":"Permalink to “CIO 真正需要 DevOps 团队做什么？”"},"​")],-1)),e[19]||(e[19]=s("blockquote",null,[s("p",null,"DevOps 团队需要 IT 领导者关注三件事：沟通、技术债务和信任。")],-1)),e[20]||(e[20]=s("p",null,[s("img",{src:"https://enterprisersproject.com/sites/default/files/styles/620x350/public/cio_cloud_2.png?itok=wGdeAHVn",alt:""})],-1)),s("p",null,[e[2]||(e[2]=t("IT 领导者可以从大量的 ",-1)),r(p,{href:"https://enterprisersproject.com/tags/devops"},{default:l(()=>[...e[0]||(e[0]=[t("DevOps",-1)])]),_:1}),e[3]||(e[3]=t(" 材料和 ",-1)),r(p,{href:"https://www.redhat.com/en/insights/devops?intcmp=701f2000000tjyaAAA"},{default:l(()=>[...e[1]||(e[1]=[t("向 DevOps 转变",-1)])]),_:1}),e[4]||(e[4]=t(" 所要求的文化挑战中学习。但是，你在一个 DevOps 团队面对长期或短期的团结挑战的调整中 —— 一个 CIO 真正需要他们做的是什么呢？",-1))]),e[21]||(e[21]=d('<p>在我与 DevOps 团队成员的谈话中，我听到的其中一些内容让你感到非常的意外。DevOps 专家（无论是内部团队的还是外部团队的）都希望将下列的事情放在你的 CIO 优先关注的级别。</p><h3 id="_1-沟通" tabindex="-1">1. 沟通 <a class="header-anchor" href="#_1-沟通" aria-label="Permalink to “1. 沟通”">​</a></h3><p>第一个也是最重要的一个，DevOps 专家需要面对面的沟通。一个经验丰富的 DevOps 团队是非常了解当前 DevOps 的趋势，以及成功和失败的经验，并且他们非常乐意去分享这些信息。表达 DevOps 的概念是很困难的，因此，要在这种新的工作关系中保持开放，定期（不用担心，不用每周）讨论有关你的 IT 的当前状态，如何评价你的沟通环境，以及你的整体的 IT 产业。</p><p>相反，你应该准备好与 DevOps 团队去共享当前的业务需求和目标。业务不再是独立于 IT 的东西：它们现在是驱动 IT 发展的重要因素，并且 IT 决定了你的业务需求和目标运行的效果如何。</p><p>注重参与而不是领导。在需要做决策的时候，你仍然是最终的决策者，但是，理解这些决策的最好方式是协作，这样，你的 DevOps 团队将有更多的自主权，并因此受到更多激励。</p><h3 id="_2-降低技术债务" tabindex="-1">2. 降低技术债务 <a class="header-anchor" href="#_2-降低技术债务" aria-label="Permalink to “2. 降低技术债务”">​</a></h3><p>第二，力争更好地理解技术债务，并在 DevOps 中努力降低它。你的 DevOps 团队都工作于一线。这里，“技术债务”是指在一个庞大的、不可持续发展的环境之中，通过维护和增加新功能而占用的人力资源和基础设备资源（查看 Rube Goldberg）。</p><p>CIO 常见的问题包括：</p><ul><li>为什么我们要用一种新方法去做这件事情？</li><li>为什么我们要在它上面花费时间和金钱？</li><li>如果这里没有新功能，只是现有组件实现了自动化，那么我们的收益是什么？</li></ul><p>“如果没有坏，就不要去修理它”，这样的事情是可以理解的。但是，如果你正在路上好好的开车，而每个人都加速超过你，这时候，你的环境就被破坏了。持续投入宝贵的资源去支撑或扩张拼凑起来的环境。</p><p>选择妥协，并且一个接一个的打补丁，以这种方式去处理每个独立的问题，结果将从一开始就变得很糟糕 —— 在一个不能支撑建筑物的地基上，一层摞一层地往上堆。事实上，这种方法就像不断地在电脑中插入坏磁盘一样。迟早有一天，面对出现的问题你将会毫无办法。在外面持续增加的压力下，整个事情将变得一团糟，完全吞噬掉你的资源。</p><p>这种情况下，解决方案就是：自动化。使用自动化的结果是良好的可伸缩性 —— 每个维护人员在 IT 环境的维护和增长方面花费更少的努力。如果增加人力资源是实现业务增长的唯一办法，那么，可伸缩性就是白日做梦。</p><p>自动化降低了你的人力资源需求，并且对持续进行的 IT 提供了更灵活的需求。很简单，对吗？是的，但是你必须为迟到的满意做好心理准备。为了在提高生产力和效率的基础上获得后端经济效益，需要预先投入时间和精力对架构和结构进行变更。为了你的 DevOps 团队能够成功，接受这些挑战，对 IT 领导者来说是非常重要的。</p><h3 id="_3-信任" tabindex="-1">3. 信任 <a class="header-anchor" href="#_3-信任" aria-label="Permalink to “3. 信任”">​</a></h3><p>最后，相信你的 DevOps 团队并且一定要理解他们。DevOps 专家也知道这个要求很难，但是他们必须得到你的强大支持和你积极参与的意愿。因为 DevOps 团队持续改进你的 IT 环境，他们自身也在不断地适应这些变化的技术，而这些变化通常正是 “你要去学习的经验”。</p><p>倾听，倾听，倾听他们，并且相信他们。DevOps 的改变是非常有价值的，而且也是值的去投入时间和金钱的。它可以提高效率、生产力、和业务响应能力。信任你的 DevOps 团队，并且给予他们更多的自由，实现更高效率的 IT 改进。</p><p>新 CIO 的底线是：将你的 DevOps 团队的潜力最大化，离开你的领导 “舒适区”，拥抱一个 “CIOps&quot; 的转变。通过 DevOps 转变，持续地与你的 DevOps 团队共同成长，以帮助你的组织获得长期的 IT 成功。</p><hr>',18)),s("p",null,[e[6]||(e[6]=t("via: ",-1)),r(p,{href:"https://enterprisersproject.com/article/2017/12/what-devops-teams-really-need-cio"},{default:l(()=>[...e[5]||(e[5]=[t("https://enterprisersproject.com/article/2017/12/what-devops-teams-really-need-cio",-1)])]),_:1})]),s("p",null,[e[10]||(e[10]=t("作者：",-1)),r(p,{href:"https://enterprisersproject.com/user/john-allessio"},{default:l(()=>[...e[7]||(e[7]=[t("John Allessio",-1)])]),_:1}),e[11]||(e[11]=t(" 译者：",-1)),r(p,{href:"https://github.com/qhwdw"},{default:l(()=>[...e[8]||(e[8]=[t("qhwdw",-1)])]),_:1}),e[12]||(e[12]=t(" 校对：",-1)),r(p,{href:"https://github.com/wxy"},{default:l(()=>[...e[9]||(e[9]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[15]||(e[15]=t("本文由 ",-1)),r(p,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[13]||(e[13]=[t("LCTT",-1)])]),_:1}),e[16]||(e[16]=t(" 原创编译，",-1)),r(p,{href:"https://linux.cn/"},{default:l(()=>[...e[14]||(e[14]=[t("Linux中国",-1)])]),_:1}),e[17]||(e[17]=t(" 荣誉推出",-1))])])}const b=a(O,[["render",v]]);export{x as __pageData,b as default};
